import{_ as n,C as r,o as l,c as s,j as e,a as t,E as o,aj as a}from"./chunks/framework.m090XgxO.js";const q=JSON.parse('{"title":"Segmented","description":"","frontmatter":{},"headers":[],"relativePath":"components/segmented.md","filePath":"components/segmented.md","lastUpdated":1789206102000}'),h={name:"components/segmented.md"},b={id:"segmented",tabindex:"-1"};function m(u,d,g,p,x,f){const i=r("Badge"),c=r("XhDemo");return l(),s("div",null,[e("h1",b,[d[0]||(d[0]=t("Segmented ",-1)),o(i,{type:"info",text:"分段控制器"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#segmented","aria-label":'Permalink to "Segmented <Badge type="info" text="分段控制器" />"'},"​",-1))]),d[3]||(d[3]=a('<p>一排连在一起的互斥选项，选中的那一段底下有一块会滑动的指示器。它是单选组，参与表单提交。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/segmented" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/segmented.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/segmented" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/segmented" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/segmented.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一排互斥选项：root 是 radiogroup、每段是 radio；整组只占一个 Tab 位，进组后四个方向键都能走</p>',4)),o(c,{src:"segmented/01-basic"}),d[4]||(d[4]=e("h2",{id:"示例",tabindex:"-1"},[t("示例 "),e("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),d[5]||(d[5]=e("h3",{id:"受控",tabindex:"-1"},[t("受控 "),e("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[6]||(d[6]=e("p",null,"传了 value 就由宿主说了算；值可以是 null，表示一段都没选中",-1)),o(c,{src:"segmented/02-controlled"}),d[7]||(d[7]=e("h3",{id:"撑满行宽",tabindex:"-1"},[t("撑满行宽 "),e("a",{class:"header-anchor",href:"#撑满行宽","aria-label":'Permalink to "撑满行宽"'},"​")],-1)),d[8]||(d[8]=e("p",null,"block 让整组占满一行，各段等分剩余空间，长短不一的文字也排得齐",-1)),o(c,{src:"segmented/03-block"}),d[9]||(d[9]=e("h3",{id:"竖排",tabindex:"-1"},[t("竖排 "),e("a",{class:"header-anchor",href:"#竖排","aria-label":'Permalink to "竖排"'},"​")],-1)),d[10]||(d[10]=e("p",null,"orientation 只改视觉排布，四个方向键与 Home/End 照样都能走",-1)),o(c,{src:"segmented/04-vertical"}),d[11]||(d[11]=e("h3",{id:"禁用",tabindex:"-1"},[t("禁用 "),e("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[12]||(d[12]=e("p",null,"单段禁用仍可聚焦、仍是方向键的起点，只是走不到它上面；整组禁用则谁都改不动",-1)),o(c,{src:"segmented/05-disabled"}),d[13]||(d[13]=e("h3",{id:"语气",tabindex:"-1"},[t("语气 "),e("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),d[14]||(d[14]=e("p",null,"tone 决定指示器与选中段文字用哪族颜色，六种语气各一组",-1)),o(c,{src:"segmented/06-tone"}),d[15]||(d[15]=e("h3",{id:"尺寸",tabindex:"-1"},[t("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[16]||(d[16]=e("p",null,"size 换的是段的高度、内边距与字号，指示器跟着量出来的段走",-1)),o(c,{src:"segmented/07-size"}),d[17]||(d[17]=e("h3",{id:"表单",tabindex:"-1"},[t("表单 "),e("a",{class:"header-anchor",href:"#表单","aria-label":'Permalink to "表单"'},"​")],-1)),d[18]||(d[18]=e("p",null,"给了 name 才带上隐藏输入参与提交；宿主表单点重置，选中值回落到 default-value",-1)),o(c,{src:"segmented/08-form"}),d[19]||(d[19]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>二到五个平级选项之间切换：视图模式（列表 / 网格）、时间粒度（日 / 周 / 月）、排序方式。</li><li>选项少、名字短，且值得一直摊开给用户看——分段控件的价值就在于不用点开就知道有哪几个。</li><li>需要随表单一起提交这个选择。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>选项超过六个，或选项文字长短悬殊：改用<a href="./radio-group">单选组</a>竖排，或<a href="./select">选择器</a>收进浮层。</li><li>需要多选，或表达的是按钮的按下态而不是一个字段值：用<a href="./toggle-group">切换按钮组</a>——它没有 <code>name</code>、不参与表单，也没有滑动指示器。</li><li>切换的是同一块区域的几屏内容：那是<a href="./tabs">标签页</a>，它管的是面板的显隐，不是一个值。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>集合入口：给 <code>collection</code> 就只交数据，条目文本与禁用都以数据为准；要改结构再写部件。</li><li>受控与非受控两态齐全：<code>value</code> 给了即受控，只发 <code>onValueChange</code> 不自改。</li><li>参与表单：给 <code>name</code> 后隐藏输入才带上它；宿主表单点重置，选中值回落到 <code>defaultValue</code>。隐藏输入只在「只交 <code>collection</code>、由组件铺开结构」时自动铺；自己写默认插槽排版的话，得记得放一个隐藏输入部件，否则给了 <code>name</code> 也没有任何东西参与提交。</li><li>指示器位置由组件量出来，横排竖排、ltr 与 rtl 都是同一条规则。</li><li>语气 · 尺寸两轴与其余组件同源；<code>block</code> 让整组撑满行宽、各段等分。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-segmented&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSegmentedHiddenInput</code> <code>XhSegmentedIndicator</code> <code>XhSegmentedItem</code> <code>XhSegmentedItemText</code> <code>XhSegmentedRoot</code></td></tr><tr><td>组合式函数</td><td><code>useSegmented</code></td></tr><tr><td>状态机</td><td><code>segmentedMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/segmented.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;segmented&quot;</code>：<strong><code>root</code></strong> · <strong><code>item</code></strong> · <code>item-text</code> · <code>indicator</code> · <code>hidden-input</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>SegmentedNode[]</code></td><td></td><td>条目数据，显示文本与禁用的事实源。给了它，条目部件只需报 value。 缺省即回到「文本与禁用都写在条目部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>选中值。给定即受控：内部不再自改，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整组禁用：条目全部 aria-disabled，点击与方向键都不生效。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：选不动，但仍可聚焦、方向键照常移焦点，对比度不降。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改呈现，不挡交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起用，只发无障碍属性，不自行拦提交。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名。给定后隐藏输入才带 name 并参与提交。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>视觉排布，默认 horizontal。方向键接受的轴与它无关（四个方向键恒响应）。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，只改写左右方向键的语义与指示器的起始缘，上下键与之无关。 不给即从根节点的计算样式现读（祖先链上的 dir 与 CSS direction 都算），给了就以它为准。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>block</code></td><td><code>boolean</code></td><td></td><td>撑满行宽，各段等分剩余空间。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: SegmentedValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>SegmentedValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | null }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSegmentedRoot</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhSegmentedRoot</code></td><td><code>item</code></td><td><code>SegmentedNodeMeta</code></td><td>铺开 collection 时每一段的文本插槽。</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>GROUP.BLUR</code> · <code>INDICATOR.MEASURE</code> · <code>FORM.RESET</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useSegmented</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td>当前选中值；一个都没选中时为 null。</td></tr><tr><td><code>collection</code></td><td><code>readonly SegmentedNodeMeta[]</code></td><td>collection 推出的条目元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td></td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>重量一遍指示器。选中值变化与 collection 增删改名都会自动重量，根的尺寸变化由尺寸观察器接住； 剩下这一类要手动叫：段的文字由部件手写（没走 collection）而后改动，或字体加载完把段撑宽了。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: SegmentedItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: SegmentedItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>选中值随这份原生输入提交。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点落到锚点段（即选中段），锚点缺席或被禁用时先落容器再由它转投首个可停留段</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in group, 组未禁用</td><td>焦点移到下一个可停留段并选中它（禁用段跳过、尽头按 loop 回绕）；只读时焦点照走但不落值；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in group, 组未禁用</td><td>焦点移到上一个可停留段并选中它；只读时焦点照走但不落值；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Home</code></td><td>focus in group, 组未禁用</td><td>焦点移到首个可停留段并选中它；只读时只移焦点</td></tr><tr><td><code>End</code></td><td>focus in group, 组未禁用</td><td>焦点移到末个可停留段并选中它；只读时只移焦点</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, 该段未禁用且组非只读</td><td>选中当前段；段是原生 button，这两个键由平台翻成 click</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根节点是 <code>radiogroup</code>，每一段是 <code>radio</code> 并显式报 <code>aria-checked</code>。</li><li>整组只占一个 Tab 位，组内靠方向键走，Home/End 直达首末段；焦点进组落在已选中的那一段上。</li><li>禁用的段用 <code>aria-disabled</code> 而不是原生 <code>disabled</code>：它仍然可以聚焦、仍然是方向键的起点。</li><li>组本身没有可见标题，请自己给根节点写 <code>aria-label</code> 或 <code>aria-labelledby</code>，否则读屏只会念&quot;单选组&quot;。</li><li>指示器是纯装饰，对读屏隐藏；&quot;当前是哪一段&quot;靠段自己的选中态表达，指示器不渲染也读得出来。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/segmented.css</code> 按部件选择：<code>[data-scope=&quot;segmented&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-block</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>indicator</code></td><td><code>data-value</code></td><td>context.get(&#39;value&#39;)</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-segmented-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-subtle</code></td><td>segmented 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-segmented-bg-disabled</code></td><td><code>root</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-bg-muted</code></td><td>segmented 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-segmented-border</code></td><td><code>root</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-border-subtle</code></td><td>segmented 的 root 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-segmented-border-invalid</code></td><td><code>root</code></td><td><code>border-color</code></td><td><code>invalid</code></td><td><code>--xh-border-invalid</code></td><td>segmented 的 root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_segmented-font-size</code></td><td>segmented 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-segmented-h</code></td><td><code>item</code><br><code>root</code></td><td><code>min-block-size</code></td><td><code>orientation=horizontal</code></td><td><code>--xh-_segmented-h</code></td><td>segmented 的 item、root 部件 min-block-size 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-bg</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_segmented-indicator-bg</code></td><td>segmented 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-radius</code></td><td><code>indicator</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>segmented 的 indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-shadow</code></td><td><code>indicator</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-elevation-raised</code></td><td>segmented 的 indicator 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-segmented-indicator-shadow-disabled</code></td><td><code>indicator</code><br><code>root</code></td><td><code>box-shadow</code></td><td><code>disabled</code></td><td><code>none</code></td><td>segmented 的 indicator、root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-bg-hover</code></td><td><code>item</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>not([data-disabled])</code><br><code>not([data-state=&#39;checked&#39;])</code><br><code>state=checked</code></td><td><code>--xh-bg-subtle-hover</code></td><td>segmented 的 item 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg</code></td><td><code>item</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg-checked</code></td><td><code>item</code></td><td><code>color</code></td><td><code>state=checked</code></td><td><code>--xh-_segmented-fg-selected</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg-checked-disabled</code></td><td><code>item</code></td><td><code>color</code></td><td><code>disabled</code><br><code>state=checked</code></td><td><code>--xh-_segmented-fg-selected</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-fg-hover</code></td><td><code>item</code></td><td><code>color</code></td><td><code>disabled</code><br><code>hover</code><br><code>not([data-disabled])</code><br><code>not([data-state=&#39;checked&#39;])</code><br><code>state=checked</code></td><td><code>--xh-fg-default</code></td><td>segmented 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-font-weight</code></td><td><code>item</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>segmented 的 item 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-gap</code></td><td><code>item</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_segmented-gap</code></td><td>segmented 的 item 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-h</code></td><td><code>item</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_segmented-h</code></td><td>segmented 的 item 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-press-scale</code></td><td><code>item</code></td><td><code>scale</code></td><td><code>active</code><br><code>disabled</code><br><code>not([data-disabled])</code><br><code>not([data-readonly])</code><br><code>readonly</code></td><td><code>--xh-motion-scale-press</code></td><td>segmented 的 item 部件 scale 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-px</code></td><td><code>item</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_segmented-px</code></td><td>segmented 的 item 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-segmented-item-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>segmented 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-segmented-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>segmented 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-segmented-track-padding</code></td><td><code>item</code><br><code>root</code></td><td><code>min-block-size</code><br><code>padding</code></td><td><code>default</code><br><code>orientation=horizontal</code></td><td><code>--xh-space-0_5</code></td><td>segmented 的 item、root 部件 min-block-size、padding 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background-color</code> · <code>block-size</code> · <code>box-shadow</code> · <code>color</code> · <code>inline-size</code> · <code>inset-block-start</code> · <code>inset-inline-start</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤另按输入能力分档：<code>pointer: coarse</code>——同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>方向从 DOM 现读：整页或某个祖先声明了 <code>dir=&#39;rtl&#39;</code>（或 CSS <code>direction</code>），左右方向键的语义与指示器的起始缘就一起翻过来，不必再给组件传一遍。上下键不受影响。</li><li><code>dir</code> 属性是显式覆盖：给了就以它为准，用在「整页 ltr、局部一块 rtl」这类场合。</li><li>指示器的偏移按逻辑起始缘量，rtl 下自动从右缘算起，不必另写一套样式。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放进<a href="./field">表单字段</a>里，让标签、说明与错误文案一并接上。</li><li>与<a href="./tabs">标签页</a>搭：分段控件切数据口径，标签页切内容面板，两者不要互相顶替。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>各段文字长度尽量接近：长短悬殊时指示器一滑，整排宽度会跟着跳。</li><li>段数固定下来再上：分段控件不适合数量会变的选项集。</li><li>选中态别只靠指示器的颜色区分，文字色也要跟着变，色觉障碍的用户才分得出。</li><li>段的文字不走 <code>collection</code> 而是自己手写、且会在运行期改动时，改完叫一次 <code>measure()</code>：指示器只跟着选中值、集合与根的尺寸走，段内文字撑宽了它看不见。</li><li>动态摘掉正持有焦点的那一段（比如按权限过滤掉它）之后，焦点会掉回 <code>&lt;body&gt;</code>。组件只保证 Tab 位退回容器、键盘还进得来；要不丢位置，得由页面自己把焦点挪到相邻的那一段上。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把它当按钮组用：段是一个值的几个取值，不是几个动作。要触发动作用<a href="./button-group">按钮组</a>。</li><li>一行里塞七八段：那已经是个下拉框了，还占着整行宽度。</li><li>用它切换整页内容却不改地址：用户刷新一次就回到了第一段。</li></ul>',56))])}const P=n(h,[["render",m]]);export{q as __pageData,P as default};
